// Toledo uses IEEE 754 float32 big-endian across 2 Modbus registers
var data = msg.payload;
if (!data || data.length < 2) { return null; }

var buf = Buffer.allocUnsafe(4);
buf.writeUInt16BE(data[0], 0);
buf.writeUInt16BE(data[1], 2);
var kg = buf.readFloatBE(0);

// Dead-band: skip if change < 0.5 kg
var last = context.get('lastKg') || 0;
if (Math.abs(kg - last) < 0.5) { return null; }
context.set('lastKg', kg);

msg.payload = parseFloat(kg.toFixed(3)).toString();
msg.topic = 'guaycampo/' + env.get('TENANT_SLUG') + '/scale/' + env.get('SCALE_ID') + '/weight';
return msg;

var value = parseFloat(msg.payload);
if (isNaN(value)) { node.warn('Invalid temperature: ' + msg.payload); return null; }

var key = 'last_' + msg.topic;
var last = context.get(key);
if (last !== undefined && Math.abs(value - last) < 0.2) { return null; }
context.set(key, value);

// Normalise topic: sensors/<siloId>/temperature → guaycampo/<tenant>/silo/<siloId>/temperature
var parts = msg.topic.split('/');
var siloId = parts[1] || 'unknown';
msg.topic = 'guaycampo/' + env.get('TENANT_SLUG') + '/silo/' + siloId + '/temperature';
msg.payload = value.toFixed(2);
return msg;

var value = parseFloat(msg.payload);
if (isNaN(value)) return null;

var parts = msg.topic.split('/');
// guaycampo/<tenant>/silo/<siloId>/<sensorType>
var tenant   = parts[1];
var siloId   = parts[3];
var sensor   = parts[4];

// Configurable thresholds (extend as needed)
var thresholds = {
  temperature: { warning: 28, critical: 35 },
  humidity:    { warning: 14, critical: 16 },
  co2:         { warning: 1000, critical: 2000 },
};

var thr = thresholds[sensor];
if (!thr) return null;

var severity = null;
if (value >= thr.critical) severity = 'critical';
else if (value >= thr.warning) severity = 'warning';
if (!severity) return null;

msg.payload = JSON.stringify({
  siloId,
  tenantSlug: tenant,
  sensorType: sensor,
  value,
  severity,
  message: sensor + ' ' + severity + ': ' + value + ' (threshold: ' + thr[severity] + ')',
  timestamp: new Date().toISOString(),
});
msg.headers = { 'Content-Type': 'application/json' };
msg.url = (env.get('SILOS_API_URL') || 'http://localhost:3003') + '/api/alerts';
return msg;

var body = msg.payload || {};
var cameraId  = body.cameraId  || env.get('DEFAULT_CAMERA_ID') || 'entrada';
var ticketId  = body.ticketId  || '';
var weighType = body.weighType || 'gross';

// Store for later
flow.set('ticketId',  ticketId);
flow.set('weighType', weighType);
flow.set('cameraId',  cameraId);

// Request snapshot from IoT bridge OCR endpoint
msg.url    = (env.get('IOT_BRIDGE_URL') || 'http://localhost:3008') + '/api/ocr/' + cameraId + '/capture';
msg.method = 'POST';
msg.payload = JSON.stringify({ ticketId, weighType });
msg.headers = { 'Content-Type': 'application/json' };
return msg;

var result = msg.payload || {};
var text       = result.text || '';
var confidence = result.confidence || 0;
var cameraId   = flow.get('cameraId') || '';

node.log('OCR result from camera ' + cameraId + ': "' + text + '" (confidence: ' + confidence + ')');

// Build HTTP response
msg.statusCode = 200;
msg.payload = JSON.stringify({
  success: true,
  cameraId,
  text,
  confidence,
  timestamp: new Date().toISOString(),
});
msg.headers = { 'Content-Type': 'application/json' };
return msg;
